class Solution {
public:
    int minSpaceWastedKResizing(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> cost(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            int mx = 0, total = 0;
            for (int j = i; j < n; j++) {
                mx = max(mx, nums[j]);
                total += nums[j];
                cost[i][j] = mx * (j - i + 1) - total;
            }
        }
        vector<int> dp(n);
        for (int i = 0; i < n; i++) dp[i] = cost[0][i];

        for (int step = 0; step < k; step++) {
            vector<int> newDp = dp;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    newDp[i] = min(newDp[i], dp[j] + cost[j + 1][i]);
                }
            }
            dp = newDp;
        }
        return dp[n - 1];
    }
};

class Solution {
    public int minSpaceWastedKResizing(int[] nums, int k) {
        int n = nums.length;
        int[][] cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            int mx = 0, total = 0;
            for (int j = i; j < n; j++) {
                mx = Math.max(mx, nums[j]);
                total += nums[j];
                cost[i][j] = mx * (j - i + 1) - total;
            }
        }
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) dp[i] = cost[0][i];

        for (int step = 0; step < k; step++) {
            int[] newDp = dp.clone();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    newDp[i] = Math.min(newDp[i], dp[j] + cost[j + 1][i]);
                }
            }
            dp = newDp;
        }
        return dp[n - 1];
    }
}

var minSpaceWastedKResizing = function(nums, k) {
  const n = nums.length;
  const cost = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    let mx = 0, total = 0;
    for (let j = i; j < n; j++) {
      mx = Math.max(mx, nums[j]);
      total += nums[j];
      cost[i][j] = mx * (j - i + 1) - total;
    }
  }
  let dp = cost[0].slice();
  for (let step = 0; step < k; step++) {
    const newDp = dp.slice();
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < i; j++) {
        newDp[i] = Math.min(newDp[i], dp[j] + cost[j + 1][i]);
      }
    }
    dp = newDp;
  }
  return dp[n - 1];
};
